 61→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 62→	logCtx := logging.WithComponent(ctx, "attach")
 63→
 64→	// Validate session ID format
 65→	if err := validation.ValidateSessionID(sessionID); err != nil {
 66→		return fmt.Errorf("invalid session ID: %w", err)
 67→	}
 68→
 69→	// Ensure we're in a git repo
 70→	repoRoot, err := paths.WorktreeRoot(ctx)
 71→	if err != nil {
 72→		return fmt.Errorf("not a git repository: %w", err)
 73→	}
 74→
 75→	// Bail out early if repo has no commits (strategy requires HEAD)
 76→	if repo, repoErr := strategy.OpenRepository(ctx); repoErr == nil && strategy.IsEmptyRepository(repo) {
 77→		return errors.New("repository has no commits yet — make an initial commit before running attach")
 78→	}
 79→
 80→	// Check session isn't already tracked
 81→	store, err := session.NewStateStore(ctx)
 82→	if err != nil {
 83→		return fmt.Errorf("failed to open session store: %w", err)
 84→	}
 85→	existing, err := store.Load(ctx, sessionID)
 86→	if err != nil {
 87→		return fmt.Errorf("failed to check existing session: %w", err)
 88→	}
 89→	if existing != nil {
 90→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 91→	}
 92→
 93→	// Resolve agent and transcript path (auto-detect agent if transcript not found)
 94→	ag, err := agent.Get(agentName)
 95→	if err != nil {
 96→		return fmt.Errorf("agent %q not available: %w", agentName, err)
 97→	}
 98→
 99→	transcriptPath, err := resolveAndValidateTranscript(logCtx, sessionID, agentName, ag)
100→	if err != nil {
101→		// Try other agents to auto-detect
102→		if detectedAg, detectedPath, detectErr := detectAgentByTranscript(logCtx, sessionID, agentName); detectErr == nil {
103→			ag = detectedAg
104→			transcriptPath = detectedPath
105→			logging.Info(logCtx, "auto-detected agent from transcript", "agent", ag.Name())
106→			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
107→		} else {
108→			return err // return original error
109→		}
110→	}
111→	agentType := ag.Type()
112→
113→	// Read transcript data
114→	transcriptData, err := ag.ReadTranscript(transcriptPath)
115→	if err != nil {
116→		return fmt.Errorf("failed to read transcript: %w", err)
117→	}
118→
119→	// Extract modified files from transcript
120→	var modifiedFiles []string
121→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
122→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
123→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
124→		} else {
125→			modifiedFiles = files
126→		}
127→	}
128→
129→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
130→	changes, err := DetectFileChanges(ctx, nil)
131→	if err != nil {
132→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
133→	}
134→
135→	// Filter and normalize paths
136→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
137→	var relNewFiles, relDeletedFiles []string
138→	if changes != nil {
139→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
140→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
141→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
142→	}
143→
144→	// Filter to uncommitted files only
145→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
146→
147→	if err := strategy.EnsureSetup(ctx); err != nil {
148→		return fmt.Errorf("failed to set up strategy: %w", err)
149→	}
150→
151→	// Create session metadata directory and copy transcript
152→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
153→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
154→	if err != nil {
155→		return fmt.Errorf("failed to resolve session directory path: %w", err)
156→	}
157→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
158→		return fmt.Errorf("failed to create session directory: %w", err)
159→	}
160→	// Normalize Gemini transcripts so the content field is a plain string
161→	// (Gemini user messages use [{"text":"..."}] arrays, which the UI can't render).
162→	storedTranscript := transcriptData
163→	if agentType == agent.AgentTypeGemini {
164→		if normalized, normErr := normalizeGeminiTranscript(transcriptData); normErr == nil {
165→			storedTranscript = normalized
166→		} else {
167→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
168→		}
169→	}
170→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
171→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
172→		return fmt.Errorf("failed to write transcript: %w", err)
173→	}
174→
175→	// Get git author
176→	author, err := GetGitAuthor(ctx)
177→	if err != nil {
178→		return fmt.Errorf("failed to get git author: %w", err)
179→	}
180→
181→	// Extract first prompt from transcript for the commit message
182→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
183→	commitMessage := generateCommitMessage(firstPrompt, agentType)
184→
185→	// Write prompt.txt so SaveStep includes it on the shadow branch
186→	// and CondenseSession can read it for the checkpoint metadata.
187→	if firstPrompt != "" {
188→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
189→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
190→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
191→		}
192→	}
193→
194→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it.
195→	// Use logFile (the normalized local copy) as the transcript path so that
196→	// CondenseSession reads the normalized version instead of the raw agent file.
197→	strat := GetStrategy(ctx)
198→	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
199→		return fmt.Errorf("failed to initialize session: %w", err)
200→	}
201→
202→	// Enrich session state with transcript-derived metadata
203→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile); err != nil {
204→		return err
205→	}
206→
207→	// Build step context and save checkpoint.
208→	// Use the local (potentially normalized) transcript so SaveStep stores the cleaned version.
209→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
210→
211→	stepCtx := strategy.StepContext{
212→		SessionID:      sessionID,
213→		ModifiedFiles:  relModifiedFiles,
214→		NewFiles:       relNewFiles,
215→		DeletedFiles:   relDeletedFiles,
216→		MetadataDir:    sessionDir,
217→		MetadataDirAbs: sessionDirAbs,
218→		CommitMessage:  commitMessage,
219→		TranscriptPath: logFile,
220→		AuthorName:     author.Name,
221→		AuthorEmail:    author.Email,
222→		AgentType:      agentType,
223→	}
224→
225→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
226→		return fmt.Errorf("failed to save checkpoint: %w", err)
227→	}
228→
229→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
230→
231→	// Print confirmation
232→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
233→	if totalChanges > 0 {
234→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
235→	} else {
236→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
237→	}
238→	if condenseErr != nil {
239→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
240→	}
241→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
242→
243→	// Offer to amend the last commit with the checkpoint trailer
244→	if checkpointIDStr != "" {
245→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
246→			logging.Warn(logCtx, "failed to amend commit", "error", err)
247→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
248→		}
249→	}
250→
251→	return nil
252→}
