254→// enrichSessionState loads the session state after initialization and populates it with
255→// transcript-derived metadata (token usage, turn count, model name, duration).
256→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string) error {
257→	state, err := strategy.LoadSessionState(ctx, sessionID)
258→	if err != nil {
259→		return fmt.Errorf("failed to load session state: %w", err)
260→	}
261→	if state == nil {
262→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
263→	}
264→	state.CLIVersion = versioninfo.Version
265→	state.TranscriptPath = transcriptPath
266→
267→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
268→		state.TokenUsage = usage
269→	}
270→	if turns := countUserTurns(transcriptData); turns > 0 {
271→		state.SessionTurnCount = turns
272→	}
273→	if model := extractModelFromTranscript(transcriptData); model != "" {
274→		state.ModelName = model
275→	}
276→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
277→		state.SessionDurationMs = dur
278→	}
279→
280→	if err := strategy.SaveSessionState(ctx, state); err != nil {
281→		return fmt.Errorf("failed to save session state: %w", err)
282→	}
283→	return nil
284→}
