286→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
287→// Returns the checkpoint ID string and any condensation error.
288→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
289→	var checkpointIDStr string
290→	var condenseErr error
291→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
292→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
293→		condenseErr = err
294→	}
295→
296→	// Single load serves both checkpoint ID extraction and finalization
297→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
298→	if loadErr != nil {
299→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
300→		return checkpointIDStr, condenseErr
301→	}
302→	if state == nil {
303→		return checkpointIDStr, condenseErr
304→	}
305→
306→	if condenseErr == nil {
307→		checkpointIDStr = state.LastCheckpointID.String()
308→	}
309→
310→	now := time.Now()
311→	state.LastInteractionTime = &now
312→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
313→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
314→	}
315→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
316→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
317→	}
318→
319→	return checkpointIDStr, condenseErr
320→}
