322→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
323→// project directories if needed.
324→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
325→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
326→	if err != nil {
327→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
328→	}
329→	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
330→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
331→		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
332→			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
333→		}
334→	}
335→	// Agents use cwd-derived project directories, so the transcript may be stored under
336→	// a different project directory if the session was started from a different working directory.
337→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
338→		return transcriptPath, nil
339→	}
340→	found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag)
341→	if searchErr == nil {
342→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
343→		return found, nil
344→	}
345→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
346→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
347→}
