349→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
350→// transcript resolution succeeds for the given session ID.
351→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
352→	for _, name := range agent.List() {
353→		if name == skip {
354→			continue
355→		}
356→		ag, err := agent.Get(name)
357→		if err != nil {
358→			continue
359→		}
360→		if path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, name, ag); resolveErr == nil {
361→			return ag, path, nil
362→		}
363→	}
364→	return nil, "", errors.New("transcript not found for any registered agent")
365→}
