367→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
368→// When force is true, it amends without prompting.
369→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
370→	// Get HEAD commit info
371→	repo, err := openRepository(ctx)
372→	if err != nil {
373→		return fmt.Errorf("failed to open repository: %w", err)
374→	}
375→	headRef, err := repo.Head()
376→	if err != nil {
377→		return fmt.Errorf("failed to get HEAD: %w", err)
378→	}
379→	headCommit, err := repo.CommitObject(headRef.Hash())
380→	if err != nil {
381→		return fmt.Errorf("failed to get HEAD commit: %w", err)
382→	}
383→
384→	shortHash := headRef.Hash().String()[:7]
385→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
386→
387→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
388→
389→	amend := true
390→	if !force {
391→		form := NewAccessibleForm(
392→			huh.NewGroup(
393→				huh.NewConfirm().
394→					Title("Amend the last commit in this branch?").
395→					Affirmative("Y").
396→					Negative("n").
397→					Value(&amend),
398→			),
399→		)
400→		if err := form.Run(); err != nil {
401→			return fmt.Errorf("prompt failed: %w", err)
402→		}
403→	}
404→
405→	if !amend {
406→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
407→		return nil
408→	}
409→
410→	// Skip amending if this exact checkpoint ID is already in the commit
411→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
412→		if existing.String() == checkpointIDStr {
413→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
414→			return nil
415→		}
416→	}
417→
418→	// Amend the commit with the checkpoint trailer.
419→	// If the message already has trailers, append on a new line; otherwise add a blank line first.
420→	trimmed := strings.TrimRight(headCommit.Message, "\n")
421→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointIDStr)
422→	var newMessage string
423→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
424→		newMessage = fmt.Sprintf("%s\n%s\n", trimmed, trailer)
425→	} else {
426→		newMessage = fmt.Sprintf("%s\n\n%s\n", trimmed, trailer)
427→	}
428→
429→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
430→	if output, err := cmd.CombinedOutput(); err != nil {
431→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
432→	}
433→
434→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
435→	return nil
436→}
