438→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
439→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
440→func extractFirstPromptFromTranscript(data []byte) string {
441→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
442→	lines, err := transcript.ParseFromBytes(data)
443→	if err == nil {
444→		for _, line := range lines {
445→			if line.Type == transcript.TypeUser {
446→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
447→					return prompt
448→				}
449→			}
450→		}
451→	}
452→
453→	// Fallback: try Gemini JSON format {"messages": [...]}
454→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
455→		return prompts[0]
456→	}
457→
458→	return ""
459→}
460→
461→// normalizeGeminiTranscript normalizes user message content fields in-place from
462→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
463→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
464→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
465→	var raw map[string]json.RawMessage
466→	if err := json.Unmarshal(data, &raw); err != nil {
467→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
468→	}
469→
470→	messagesRaw, ok := raw["messages"]
471→	if !ok {
472→		return data, nil
473→	}
474→
475→	var messages []json.RawMessage
476→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
477→		return nil, fmt.Errorf("failed to parse messages: %w", err)
478→	}
479→
480→	changed := false
481→	for i, msgRaw := range messages {
482→		var msg map[string]json.RawMessage
483→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
484→			continue
485→		}
486→
487→		contentRaw, hasContent := msg["content"]
488→		if !hasContent || len(contentRaw) == 0 {
489→			continue
490→		}
491→
492→		// Skip if already a string
493→		var strContent string
494→		if json.Unmarshal(contentRaw, &strContent) == nil {
495→			continue
496→		}
497→
498→		// Try to convert array of {"text":"..."} to a plain string
499→		var parts []struct {
500→			Text string `json:"text"`
501→		}
502→		if json.Unmarshal(contentRaw, &parts) != nil {
503→			continue
504→		}
505→
506→		var texts []string
507→		for _, p := range parts {
508→			if p.Text != "" {
509→				texts = append(texts, p.Text)
510→			}
511→		}
512→		joined := strings.Join(texts, "\n")
513→		strBytes, err := json.Marshal(joined)
514→		if err != nil {
515→			continue
516→		}
517→		msg["content"] = strBytes
518→		rewritten, err := json.Marshal(msg)
519→		if err != nil {
520→			continue
521→		}
522→		messages[i] = rewritten
523→		changed = true
524→	}
525→
526→	if !changed {
527→		return data, nil
528→	}
529→
530→	rewrittenMessages, err := json.Marshal(messages)
531→	if err != nil {
532→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
533→	}
534→	raw["messages"] = rewrittenMessages
535→
536→	return json.MarshalIndent(raw, "", "  ")
537→}
