539→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
540→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
541→func countUserTurns(data []byte) int {
542→	// Try JSONL format first — use ExtractUserContent to distinguish
543→	// real user prompts from tool_result messages (both have type "user").
544→	lines, err := transcript.ParseFromBytes(data)
545→	if err == nil {
546→		count := 0
547→		for _, line := range lines {
548→			if line.Type == transcript.TypeUser {
549→				if transcript.ExtractUserContent(line.Message) != "" {
550→					count++
551→				}
552→			}
553→		}
554→		if count > 0 {
555→			return count
556→		}
557→	}
558→
559→	// Fallback: Gemini JSON format
560→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
561→		return len(prompts)
562→	}
563→
564→	return 0
565→}
