567→// extractModelFromTranscript extracts the model name from a JSONL transcript.
568→// Best-effort: returns empty string if the transcript format doesn't include model info
569→// (e.g., Gemini stores model info in hook events, not the transcript).
570→func extractModelFromTranscript(data []byte) string {
571→	lines, err := transcript.ParseFromBytes(data)
572→	if err != nil {
573→		return ""
574→	}
575→
576→	for _, line := range lines {
577→		if line.Type != transcript.TypeAssistant {
578→			continue
579→		}
580→		var msg struct {
581→			Model string `json:"model"`
582→		}
583→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
584→			return msg.Model
585→		}
586→	}
587→	return ""
588→}
