590→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
591→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
592→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
593→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
594→func estimateSessionDuration(data []byte) int64 {
595→	type timestamped struct {
596→		Timestamp string `json:"timestamp"`
597→	}
598→
599→	var first, last time.Time
600→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
601→		if len(rawLine) == 0 {
602→			continue
603→		}
604→		var ts timestamped
605→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
606→			continue
607→		}
608→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
609→		if err != nil {
610→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
611→			if err != nil {
612→				continue
613→			}
614→		}
615→		if first.IsZero() {
616→			first = parsed
617→		}
618→		last = parsed
619→	}
620→
621→	if first.IsZero() || last.IsZero() || !last.After(first) {
622→		return 0
623→	}
624→	return last.Sub(first).Milliseconds()
625→}
