 40→// fileExists checks if a file exists
 41→func fileExists(path string) bool {
 42→	_, err := os.Stat(path)
 43→	return err == nil
 44→}
 45→
 46→// copyFile copies a file from src to dst using os.Root for traversal-resistant
 47→// writes (Go 1.24+). dst must be absolute and reside under either the repo
 48→// worktree root, the user's home directory (for agent session dirs such as
 49→// ~/.claude/), or the system temp directory (used during tests).
 50→// The kernel enforces that the write cannot escape the allowed directory,
 51→// eliminating TOCTOU races and symlink escapes.
 52→func copyFile(src, dst string) error {
 53→	src = filepath.Clean(src)
 54→	dst = filepath.Clean(dst)
 55→
 56→	if !filepath.IsAbs(dst) {
 57→		return fmt.Errorf("copyFile: dst must be absolute, got %q", dst)
 58→	}
 59→
 60→	input, err := os.ReadFile(src)
 61→	if err != nil {
 62→		return err //nolint:wrapcheck // already present in codebase
 63→	}
 64→
 65→	root, relPath, err := openAllowedRoot(dst)
 66→	if err != nil {
 67→		return err
 68→	}
 69→	defer root.Close()
 70→
 71→	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
 72→		return fmt.Errorf("failed to write file: %w", err)
 73→	}
 74→	return nil
 75→}
 76→
 77→// openAllowedRoot finds the allowed root directory that contains dst and returns
 78→// an os.Root handle along with the relative path within that root.
 79→// Allowed directories: repo worktree root, user home, system temp dir.
 80→// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
 81→func openAllowedRoot(dst string) (*os.Root, string, error) {
 82→	allowed := allowedRootDirs()
 83→
 84→	// Resolve the directory portion of dst through symlinks so that e.g.
 85→	// /var/folders/... matches /private/var/folders/... on macOS.
 86→	// Only the parent directory is resolved; the final component may not exist yet.
 87→	resolvedDst := dst
 88→	if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
 89→		resolvedDst = filepath.Join(r, filepath.Base(dst))
 90→	}
 91→
 92→	for _, dir := range allowed {
 93→		if !paths.IsSubpath(dir, resolvedDst) {
 94→			continue
 95→		}
 96→		rel, err := filepath.Rel(dir, resolvedDst)
 97→		if err != nil {
 98→			continue
 99→		}
100→		root, err := os.OpenRoot(dir)
101→		if err != nil {
102→			return nil, "", fmt.Errorf("openAllowedRoot: failed to open root %q: %w", dir, err)
103→		}
104→		return root, rel, nil
105→	}
106→
107→	return nil, "", fmt.Errorf("openAllowedRoot: dst %q is outside allowed directories", dst)
108→}
109→
110→// allowedRootDirs returns the list of directories that copyFile may write to.
111→// Directories are resolved through symlinks so they match resolved dst paths.
112→func allowedRootDirs() []string {
113→	allowed := make([]string, 0, 3)
114→
115→	if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
116→		allowed = appendResolved(allowed, repoRoot)
117→	}
118→	if home, err := os.UserHomeDir(); err == nil {
119→		allowed = appendResolved(allowed, home)
120→	}
121→	if tmpDir := os.TempDir(); tmpDir != "" {
122→		allowed = appendResolved(allowed, tmpDir)
123→	}
124→
125→	return allowed
126→}
127→
128→// appendResolved appends dir to the list after resolving symlinks.
129→// Falls back to the original path if symlink resolution fails.
130→func appendResolved(dirs []string, dir string) []string {
131→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
132→		return append(dirs, resolved)
133→	}
134→	return append(dirs, dir)
135→}
