 25→// PrePromptState stores the state captured before a user prompt
 26→type PrePromptState struct {
 27→	SessionID      string   `json:"session_id"`
 28→	Timestamp      string   `json:"timestamp"`
 29→	UntrackedFiles []string `json:"untracked_files"`
 30→
 31→	// TranscriptOffset is the unified transcript position when this state was captured.
 32→	// For Claude Code (JSONL), this is the line count.
 33→	// For Gemini CLI (JSON), this is the message count.
 34→	// Zero means not set or session just started.
 35→	TranscriptOffset int `json:"transcript_offset,omitempty"`
 36→
 37→	// LastTranscriptIdentifier is the agent-specific identifier at the transcript position.
 38→	// UUID for Claude Code, message ID for Gemini CLI. Optional metadata.
 39→	LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"`
 40→
 41→	// Deprecated: StartMessageIndex is the old Gemini-specific field.
 42→	// Migrated to TranscriptOffset on load.
 43→	StartMessageIndex int `json:"start_message_index,omitempty"`
 44→
 45→	// Deprecated: StepTranscriptStart is the old Claude-specific field.
 46→	// Migrated to TranscriptOffset on load.
 47→	StepTranscriptStart int `json:"step_transcript_start,omitempty"`
 48→
 49→	// Deprecated: LastTranscriptLineCount is the oldest name for transcript position.
 50→	// Migrated to TranscriptOffset on load.
 51→	LastTranscriptLineCount int `json:"last_transcript_line_count,omitempty"`
 52→}
 53→
 54→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 55→// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 56→// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 57→// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 58→// are correctly treated as new.
 59→func (s *PrePromptState) PreUntrackedFiles() []string {
 60→	if s == nil {
 61→		return nil
 62→	}
 63→	if s.UntrackedFiles == nil {
 64→		return []string{}
 65→	}
 66→	return s.UntrackedFiles
 67→}
