 69→// normalizePrePromptState migrates deprecated fields after loading from JSON.
 70→func (s *PrePromptState) normalizePrePromptState() {
 71→	// Migrate the oldest field to the intermediate field first
 72→	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 73→		s.StepTranscriptStart = s.LastTranscriptLineCount
 74→	}
 75→	s.LastTranscriptLineCount = 0
 76→
 77→	// Migrate all deprecated fields to the unified TranscriptOffset
 78→	if s.TranscriptOffset == 0 {
 79→		if s.StepTranscriptStart > 0 {
 80→			s.TranscriptOffset = s.StepTranscriptStart
 81→		} else if s.StartMessageIndex > 0 {
 82→			s.TranscriptOffset = s.StartMessageIndex
 83→		}
 84→	}
 85→	s.StepTranscriptStart = 0
 86→	s.StartMessageIndex = 0
 87→}
