352→// FilterAndNormalizePaths converts absolute paths to relative and filters out
353→// infrastructure paths and paths outside the repo.
354→func FilterAndNormalizePaths(files []string, cwd string) []string {
355→	var result []string
356→	for _, file := range files {
357→		relPath := paths.ToRelativePath(file, cwd)
358→		if relPath == "" {
359→			continue // outside repo
360→		}
361→		if paths.IsInfrastructurePath(relPath) {
362→			continue // skip .entire directory
363→		}
364→		result = append(result, relPath)
365→	}
366→	return result
367→}
