369→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
370→func mergeUnique(base, extra []string) []string {
371→	if len(extra) == 0 {
372→		return base
373→	}
374→	seen := make(map[string]bool, len(base))
375→	for _, s := range base {
376→		seen[s] = true
377→	}
378→	for _, s := range extra {
379→		if !seen[s] {
380→			seen[s] = true
381→			base = append(base, s)
382→		}
383→	}
384→	return base
385→}
