605→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
606→// It counts existing checkpoint files in the task metadata checkpoints directory.
607→// Returns 1 if no checkpoints exist yet.
608→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
609→	// Use the session ID directly as the metadata directory name
610→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
611→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
612→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
613→
614→	entries, err := os.ReadDir(checkpointsDir)
615→	if err != nil {
616→		// Directory doesn't exist or can't be read - start at 1
617→		return 1
618→	}
619→
620→	// Count JSON files (checkpoints)
621→	count := 0
622→	for _, entry := range entries {
623→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
624→			count++
625→		}
626→	}
627→
628→	return count + 1
629→}
