 25→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 26→// Computes the path dynamically from the current repo location for cross-machine portability.
 27→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 28→	repoRoot, err := paths.WorktreeRoot(ctx)
 29→	if err != nil {
 30→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 31→	}
 32→
 33→	sessionDir, err := agent.GetSessionDir(repoRoot)
 34→	if err != nil {
 35→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 36→	}
 37→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 38→}
