 40→// agentSessionBaseDirs maps agent names to the base directories that contain
 41→// per-project session subdirectories. Each agent organizes transcripts under
 42→// a per-project subdirectory within its base dir.
 43→var agentSessionBaseDirs = map[types.AgentName]func() (string, error){
 44→	agentpkg.AgentNameClaudeCode: func() (string, error) {
 45→		home, err := os.UserHomeDir()
 46→		if err != nil {
 47→			return "", fmt.Errorf("failed to get home directory: %w", err)
 48→		}
 49→		return filepath.Join(home, ".claude", "projects"), nil
 50→	},
 51→	agentpkg.AgentNameGemini: func() (string, error) {
 52→		home, err := os.UserHomeDir()
 53→		if err != nil {
 54→			return "", fmt.Errorf("failed to get home directory: %w", err)
 55→		}
 56→		return filepath.Join(home, ".gemini", "tmp"), nil
 57→	},
 58→}
 59→
 60→// searchTranscriptInProjectDirs searches for a session transcript across an agent's
 61→// project directories that could plausibly belong to the current repository.
 62→// Agents like Claude Code and Gemini CLI derive the project directory from the cwd,
 63→// so the transcript may be stored under a different project directory if the session
 64→// was started from a subdirectory.
 65→//
 66→// The search is scoped to the agent's base directory (e.g., ~/.claude/projects) and only
 67→// walks immediate subdirectories (plus one extra level for agents like Gemini that nest
 68→// chats under <project>/chats/).
 69→func searchTranscriptInProjectDirs(agentName types.AgentName, sessionID string, ag agentpkg.Agent) (string, error) {
 70→	baseDirFn, ok := agentSessionBaseDirs[agentName]
 71→	if !ok {
 72→		return "", fmt.Errorf("fallback transcript search not supported for agent %q", agentName)
 73→	}
 74→	baseDir, err := baseDirFn()
 75→	if err != nil {
 76→		return "", fmt.Errorf("failed to get base directory: %w", err)
 77→	}
 78→
 79→	// Walk subdirectories with a max depth of 3 (baseDir/project/subdir/file)
 80→	// to avoid scanning unrelated project trees.
 81→	baseDirDepth := strings.Count(filepath.Clean(baseDir), string(filepath.Separator))
 82→	const maxExtraDepth = 3
 83→
 84→	var found string
 85→	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
 86→		if err != nil {
 87→			return nil //nolint:nilerr // skip inaccessible dirs
 88→		}
 89→		if !d.IsDir() {
 90→			return nil
 91→		}
 92→		// Limit walk depth
 93→		depth := strings.Count(filepath.Clean(path), string(filepath.Separator)) - baseDirDepth
 94→		if depth > maxExtraDepth {
 95→			return filepath.SkipDir
 96→		}
 97→		candidate := ag.ResolveSessionFile(path, sessionID)
 98→		if _, statErr := os.Stat(candidate); statErr == nil {
 99→			found = candidate
100→			return filepath.SkipAll
101→		}
102→		return nil
103→	})
104→	if walkErr != nil {
105→		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
106→	}
107→	if found != "" {
108→		return found, nil
109→	}
110→	return "", errors.New("transcript not found in any project directory")
111→}
