131→// FindCheckpointUUID finds the UUID of the message containing the tool_result
132→// for the given tool_use_id. This is used to find the checkpoint point for
133→// transcript truncation when rewinding to a task.
134→// Returns the UUID and true if found, empty string and false otherwise.
135→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
136→	for _, line := range transcript {
137→		if line.Type != transcriptTypeUser {
138→			continue
139→		}
140→
141→		var msg userMessageWithToolResults
142→		if err := json.Unmarshal(line.Message, &msg); err != nil {
143→			continue
144→		}
145→
146→		for _, block := range msg.Content {
147→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
148→				return line.UUID, true
149→			}
150→		}
151→	}
152→	return "", false
153→}
