155→// TruncateTranscriptAtUUID returns transcript lines up to and including the
156→// line with the given UUID. If the UUID is not found or is empty, returns
157→// the entire transcript.
158→//
159→//nolint:revive // Exported for testing purposes
160→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
161→	if uuid == "" {
162→		return transcript
163→	}
164→
165→	for i, line := range transcript {
166→		if line.UUID == uuid {
167→			return transcript[:i+1]
168→		}
169→	}
170→
171→	// UUID not found, return full transcript
172→	return transcript
173→}
