175→// writeTranscript writes transcript lines to a file in JSONL format.
176→func writeTranscript(path string, transcript []transcriptLine) error {
177→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
178→	if err != nil {
179→		return fmt.Errorf("failed to create file: %w", err)
180→	}
181→	defer func() { _ = file.Close() }()
182→
183→	for _, line := range transcript {
184→		data, err := json.Marshal(line)
185→		if err != nil {
186→			return fmt.Errorf("failed to marshal line: %w", err)
187→		}
188→		if _, err := file.Write(data); err != nil {
189→			return fmt.Errorf("failed to write line: %w", err)
190→		}
191→		if _, err := file.WriteString("\n"); err != nil {
192→			return fmt.Errorf("failed to write newline: %w", err)
193→		}
194→	}
195→
196→	return nil
197→}
