199→// TranscriptPosition contains the position information for a transcript file.
200→type TranscriptPosition struct {
201→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
202→	LineCount int    // Total number of lines
203→}
204→
205→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
206→// Returns empty position if file doesn't exist or is empty.
207→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
208→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
209→	if path == "" {
210→		return TranscriptPosition{}, nil
211→	}
212→
213→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
214→	if err != nil {
215→		if os.IsNotExist(err) {
216→			return TranscriptPosition{}, nil
217→		}
218→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
219→	}
220→	defer func() { _ = file.Close() }()
221→
222→	var pos TranscriptPosition
223→	reader := bufio.NewReader(file)
224→
225→	for {
226→		lineBytes, err := reader.ReadBytes('\n')
227→		if err != nil && err != io.EOF {
228→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
229→		}
230→
231→		if len(lineBytes) == 0 {
232→			if err == io.EOF {
233→				break
234→			}
235→			continue
236→		}
237→
238→		pos.LineCount++
239→
240→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
241→		var line transcriptLine
242→		if err := json.Unmarshal(lineBytes, &line); err == nil {
243→			if line.UUID != "" {
244→				pos.LastUUID = line.UUID
245→			}
246→		}
247→
248→		if err == io.EOF {
249→			break
250→		}
251→	}
252→
253→	return pos, nil
254→}
