194→// GetLastMessageIDFromFile reads a transcript file and returns the last message's ID.
195→// Returns empty string if the file doesn't exist, is empty, or has no messages with IDs.
196→func GetLastMessageIDFromFile(path string) (string, error) {
197→	if path == "" {
198→		return "", nil
199→	}
200→
201→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
202→	if err != nil {
203→		if os.IsNotExist(err) {
204→			return "", nil
205→		}
206→		return "", fmt.Errorf("failed to read transcript: %w", err)
207→	}
208→
209→	if len(data) == 0 {
210→		return "", nil
